// The timeline is DATA assembled from parts, not a template with holes punched in it.
// A missing clip degrades that beat to its still frame rather than failing the render:
// a video with one static beat ships; a failed render ships nothing.
const p = $json.payload;
const beats = p.beats || [];
const clips = new Map((p.clips || []).map(c => [c.beat_index, c]));
const stills = new Map((p.stills || []).map(s => [s.beat_index, s]));
const ar = p.aspect_ratio || '9:16';
const DIMS = { '9:16': [1080, 1920], '1:1': [1080, 1080], '4:5': [1080, 1350], '16:9': [1920, 1080] };
const [width, height] = DIMS[ar] || DIMS['9:16'];

let t = 0, degraded = 0;
const tracks = beats.map((b, i) => {
  const clip = clips.get(i);
  const still = stills.get(i);
  if (!clip) degraded++;
  const el = {
    type: clip ? 'video' : 'image',
    source: clip?.uri || still?.uri || null,
    time: t,
    duration: b.duration_s,
    // A still standing in for a missing clip gets a slow push so the cut still breathes.
    animations: clip ? [] : [{ type: 'scale', easing: 'linear', start_scale: '100%', end_scale: '108%' }]
  };
  t += b.duration_s;
  return el;
});

if (tracks.some(x => !x.source)) throw new Error('VALIDATION_FAILED: a beat has neither clip nor still');

return [{ json: {
  output_format: 'mp4', width, height, frame_rate: 30,
  elements: [
    ...tracks,
    p.voiceover_uri ? { type: 'audio', source: p.voiceover_uri, time: 0 } : null,
    p.music_uri ? { type: 'audio', source: p.music_uri, time: 0, volume: 0.12, audio_fade_out: 1.5 } : null,
    ...(p.cues || []).map(c => ({ type: 'text', text: c.text, time: c.start_s, duration: Math.max(0.4, c.end_s - c.start_s), ...(p.caption_style || {}) })),
    p.end_card ? { type: 'composition', source: p.end_card, time: Math.max(0, t - 2.5), duration: 2.5 } : null
  ].filter(Boolean),
  total_duration_s: t,
  degraded_beats: degraded
} }];
